-- 0076 — PREFLIGHT. READ ONLY: one SELECT, changes nothing. Generated by supabase/live/make_blocks_pack.sh — do not edit by hand.
-- Run on the target (staging first; live only after its own approval) immediately before 0076.
-- Part 1: every row must be ok = true, or 0076 is not applied. Part 2: information only.
with checks(part, item, ok, detail) as (
  select 1, '0075 is applied (admin_blocks_received exists)', to_regproc('public.admin_blocks_received') is not null, ''
  union all select 1, 'none of 0076 exists yet (staff_block, assert_valid_block, blocks_direct_write_rules)', not exists (select 1 from pg_proc where pronamespace = 'public'::regnamespace and proname = 'staff_block') and not exists (select 1 from pg_proc where pronamespace = 'public'::regnamespace and proname = 'assert_valid_block') and not exists (select 1 from pg_proc where pronamespace = 'public'::regnamespace and proname = 'blocks_direct_write_rules'), ''
  union all select 1, 'reject_block_over_booking: the 0001–0075 version (unchanged by 0076)', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '18c335039c80db474319e30ddbde01ec' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'reject_block_over_booking'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'reject_block_over_booking'), 'missing')
  union all select 1, 'reject_booking_over_block: the 0001–0075 version (unchanged by 0076)', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '1c955f6aaf4eed5d27a8be8032ca149f' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'reject_booking_over_block'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'reject_booking_over_block'), 'missing')
  union all select 1, 'expire_stale_holds: the 0001–0075 version (unchanged by 0076)', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = 'bd5333a933065bffc0599dcee74b389d' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'expire_stale_holds'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'expire_stale_holds'), 'missing')
  union all select 1, 'assert_valid_court_slot: the 0001–0075 version (unchanged by 0076)', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '842d14da33899a48cb53eb356bdf671c' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'assert_valid_court_slot'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'assert_valid_court_slot'), 'missing')
  union all select 1, 'close_club: the 0001–0075 version (unchanged by 0076)', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '5374dc2a493362cdc644fb0c65256f42' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'close_club'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'close_club'), 'missing')
  union all select 1, 'is_staff_of: the 0001–0075 version (unchanged by 0076)', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '2fd33ea362331532c1508cdb70777296' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'is_staff_of'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'is_staff_of'), 'missing')
  union all select 1, 'overlap protection in place: block and booking triggers enabled, no_overlapping_blocks', exists (select 1 from pg_trigger where tgrelid = 'public.blocks'::regclass and tgname = 'blocks_booking_check' and tgenabled = 'O') and exists (select 1 from pg_trigger t join pg_proc p on p.oid = t.tgfoid where t.tgrelid = 'public.bookings'::regclass and p.proname = 'reject_booking_over_block' and t.tgenabled = 'O') and exists (select 1 from pg_constraint where conrelid = 'public.blocks'::regclass and conname = 'no_overlapping_blocks' and contype = 'x'), ''
  union all select 1, 'blocks policies are the 0075 ones', (select coalesce(string_agg(policyname || ' (' || cmd || ')', ', ' order by policyname), 'none') from pg_policies where schemaname = 'public' and tablename = 'blocks') = 'blocks: staff read (SELECT), blocks: staff write (ALL)', (select coalesce(string_agg(policyname || ' (' || cmd || ')', ', ' order by policyname), 'none') from pg_policies where schemaname = 'public' and tablename = 'blocks')
  union all select 1, 'blocks triggers are the 0075 ones', (select coalesce(string_agg(tgname, ', ' order by tgname), 'none') from pg_trigger where tgrelid = 'public.blocks'::regclass and not tgisinternal) = 'blocks_booking_check', (select coalesce(string_agg(tgname, ', ' order by tgname), 'none') from pg_trigger where tgrelid = 'public.blocks'::regclass and not tgisinternal)
  union all select 1, 'runs as the owner role; close_club has owner rights (the direct-write rule tells them apart)', current_user not in ('anon', 'authenticated') and (select prosecdef and pg_get_userbyid(proowner) not in ('anon', 'authenticated') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'close_club'), current_user::text
  union all select 2, 'saved blocks (compare with the postcheck: 0076 changes none)', true, (select count(*) || ' blocks, ' || coalesce(md5(string_agg(id::text || '|' || club_id || '|' || court_id || '|' || start_at || '|' || end_at || '|' || coalesce(reason, '') || '|' || created_by || '|' || created_at, ',' order by id)), '-') from public.blocks)
  union all select 2, 'saved future blocks the new rules would refuse (kept as they are)', true, (select count(*)::text from public.blocks b join public.clubs c on c.id = b.club_id where b.end_at > now() and (extract(epoch from (b.end_at - b.start_at)) % (c.slot_minutes * 60) <> 0 or (b.start_at at time zone c.timezone)::time < c.open_time or (extract(epoch from ((b.end_at at time zone c.timezone) - date_trunc('day', b.start_at at time zone c.timezone))) / 60) > extract(epoch from c.close_time) / 60 or (extract(epoch from ((b.start_at at time zone c.timezone)::time - c.open_time)) / 60)::int % c.slot_minutes <> 0))
  union all select 1, 'signed-in users can insert, update, delete and read blocks (the old website path)', has_table_privilege('authenticated', 'public.blocks', 'INSERT') and has_table_privilege('authenticated', 'public.blocks', 'UPDATE') and has_table_privilege('authenticated', 'public.blocks', 'DELETE') and has_table_privilege('authenticated', 'public.blocks', 'SELECT'), ''
)
select part, item, ok, detail from checks order by part, item;
